var e=`1431-pohnpei-banana-pudding`;var i=`world-1431`;var t=`FM`;var s=`oceania`;var o=6;var d=90;var r={en:`Pohnpei Banana Pudding`,ua:`Банановий пудинг Понпеї`};var u={en:`Pohnpei-inspired dense steamed banana-and-coconut pudding, bound with tapioca starch and wrapped in banana leaf.`,ua:`Щільний бананово-кокосовий пудинг за мотивами кухні Понпеї, загущений тапіоковим крохмалем і приготовлений у банановому листі.`};var l=[{en:`Mash very ripe bananas until mostly smooth. Mix in coconut cream and coconut sugar.`,ua:`Розімніть дуже стиглі банани майже до однорідності. Додайте кокосові вершки й кокосовий цукор.`,t:[`mashing`,`mixing`],m:7,i:[[`banana`,700,`g`],[`coconut-cream`,350,`ml`],[`coconut-sugar`,65,`g`]]},{en:`Whisk in tapioca starch and salt until no dry lumps remain; batter should be thick and spoonable.`,ua:`Умішайте тапіоковий крохмаль і сіль без сухих грудочок; маса має бути густою, але придатною для викладання ложкою.`,t:[`mixing`],m:6,i:[[`tapioca-starch`,160,`g`],[`sea-salt`,3,`g`]]},{en:`Soften food-safe banana leaves and line six small heat-safe bowls or make sealed parcels; divide batter evenly.`,ua:`Розм’якшіть харчове бананове листя, вистеліть ним шість невеликих жаростійких форм або зробіть закриті пакунки; рівномірно розподіліть масу.`,t:[`leaf-wrapping`],m:12,i:[[`banana-leaf`,6,`leaf`]]},{en:`Steam for 45–55 minutes until the centre is set and starch fully cooked; add boiling water to the steamer as needed.`,ua:`Готуйте на парі 45–55 хвилин, доки середина не стане щільною, а крохмаль повністю готовим; за потреби доливайте окріп у пароварку.`,t:[`steaming`],m:50,i:[]},{en:`Rest 15 minutes before unwrapping and cutting. Serve warm or chilled.`,ua:`Дайте постояти 15 хвилин, тоді розгорніть і наріжте. Подавайте теплим або охолодженим.`,t:[`garnishing`],m:15,i:[]}];var c={slug:e,id:i,country:`FM`,region:s,servings:6,minutes:90,title:r,text:u,steps:l};export{t as country,c as default,i as id,d as minutes,s as region,o as servings,e as slug,l as steps,u as text,r as title};